(()=>{function read(){const e=document.getElementById('port');return {root:{left:scrollX,top:scrollY},element:{left:e.scrollLeft,top:e.scrollTop}}}
 const root=document.documentElement,port=document.getElementById('port');
 document.getElementById('run').addEventListener('click',()=>{
  function go(){const css={root:getComputedStyle(root).getPropertyValue('scroll-behavior'),element:getComputedStyle(port).getPropertyValue('scroll-behavior')};const box=root,actor=window;actor.scrollTo({top:180});const immediate=read();let start=null;function capture(time){if(start===null)start=time;if(time-start<600){requestAnimationFrame(capture);return}document.getElementById('probe').textContent=JSON.stringify({css,immediate,settled:read()})}requestAnimationFrame(capture)}
  go()
 });})();

